/* @lc app=leetcode id=2382 lang=kotlin */
class Solution { fun maximumSegmentSum(nums: IntArray, q: IntArray): LongArray = LongArray(q.size).let { ans -> LongArray(q.size).let { sum -> IntArray(q.size) { it }.let { p -> { i: Int -> generateSequence(i) { p[it].takeIf { x -> p[x] != x } }.last().let { root -> generateSequence(i) { p[it].takeIf { x -> p[x] != x } }.forEach { p[it] = root }.run { root } } }.let { find -> (q.size - 1 downTo 1).fold(0L) { ms, i -> q[i].let { idx -> nums[idx].toLong().also { sum[idx] = it }.run { listOf(idx - 1, idx + 1).forEach { adj -> if (adj in q.indices && sum[adj] > 0) find(idx).let { r1 -> find(adj).let { r2 -> if (r1 != r2) r1.also { p[it] = r2 }.also { sum[r2] += sum[r1] } } } } }.run { maxOf(ms, sum[find(idx)]) } }.also { ans[i - 1] = it } }.run { ans } } } } }